	// ── Cart ───────────────────────────────────────────────────────────────
	SaveCart(context.Context, *SaveCartRequest) (*StatusResponse, error)
	GetCart(context.Context, *UserId) (*CartResponse, error)
	ClearCart(context.Context, *UserId) (*StatusResponse, error)
	// ── Quotes & orders ────────────────────────────────────────────────────
	CalculateQuote(context.Context, *QuoteRequest) (*QuoteResponse, error)
	PlaceOrder(context.Context, *OrderRequest) (*OrderResponse, error)
	GetOrder(context.Context, *OrderId) (*Order, error)
	GetUserOrders(context.Context, *GetUserOrdersRequest) (*OrderListResponse, error)
	GetAllOrders(context.Context, *GetAllOrdersRequest) (*OrderListResponse, error)
	UpdateOrderStatus(context.Context, *UpdateStatusRequest) (*StatusResponse, error)
	CancelOrder(context.Context, *CancelOrderRequest) (*StatusResponse, error)
	ReportOrderIssue(context.Context, *IssueReport) (*StatusResponse, error)
	ResolveOrderIssue(context.Context, *ResolveIssueRequest) (*StatusResponse, error)
	AssignDriver(context.Context, *AssignDriverRequest) (*StatusResponse, error)
	AddOrderNote(context.Context, *OrderNoteRequest) (*StatusResponse, error)
	// ── Warehouses / depots ────────────────────────────────────────────────
	ListWarehouses(context.Context, *Empty) (*WarehouseListResponse, error)
	AddWarehouse(context.Context, *Warehouse) (*StatusResponse, error)
	EditWarehouse(context.Context, *Warehouse) (*StatusResponse, error)
	RemoveWarehouse(context.Context, *WarehouseId) (*StatusResponse, error)
	// ── Drivers ────────────────────────────────────────────────────────────
	ListDrivers(context.Context, *ListDriversRequest) (*DriverListResponse, error)
	AddDriver(context.Context, *Driver) (*StatusResponse, error)
	EditDriver(context.Context, *Driver) (*StatusResponse, error)
	RemoveDriver(context.Context, *DriverId) (*StatusResponse, error)
	SetDriverAvailability(context.Context, *DriverAvailability) (*StatusResponse, error)
	BroadcastDrivers(context.Context, *BroadcastRequest) (*StatusResponse, error)
	// ── Promotions ────────────────────────────────────────────────────────
	ListPromos(context.Context, *Empty) (*PromoListResponse, error)
	AddPromo(context.Context, *Promo) (*StatusResponse, error)
	EditPromo(context.Context, *Promo) (*StatusResponse, error)
	RemovePromo(context.Context, *PromoId) (*StatusResponse, error)
	ApplyPromoCode(context.Context, *ApplyPromoRequest) (*PromoEffect, error)
	// ── Loyalty ───────────────────────────────────────────────────────────
	GetLoyaltyBalance(context.Context, *UserId) (*LoyaltyBalance, error)
	AdjustLoyaltyPoints(context.Context, *LoyaltyAdjustment) (*StatusResponse, error)
